<section class="section page-top"><div class="container portal-layout"><?php require ROOT_PATH.'/app/Views/client/_nav.php'; ?><div><h1>Kontrak & RAB</h1><h2>RAB</h2><?php foreach($rabs as $r): ?><article class="panel"><h3><?= e($r['project_title']) ?> — <?= e(strtoupper($r['type'])) ?></h3><p>Status: <strong><?= e($r['status']) ?></strong> • Total: <?= money($r['grand_total']) ?></p><?php if($r['type']==='final' && $r['status']==='menunggu_persetujuan'): ?><form method="post" action="<?= url('client/rab/'.$r['id'].'/approve') ?>"><?= csrf_field() ?><button class="btn primary">Setujui RAB Final</button></form><?php endif; ?></article><?php endforeach; ?><h2>Kontrak</h2><?php foreach($contracts as $c): ?><article class="panel"><h3><?= e($c['project_title']) ?></h3><p>Status: <strong><?= e($c['status']) ?></strong> • Nilai: <?= money($c['contract_value']) ?></p><?php if($c['status']==='menunggu_tanda_tangan'): ?><form method="post" action="<?= url('client/contract/'.$c['id'].'/sign') ?>"><?= csrf_field() ?><button class="btn primary">Setujui & Tandatangani Kontrak</button></form><small>Mekanisme internal ini bukan TTE tersertifikasi.</small><?php endif; ?></article><?php endforeach; ?></div></div></section>